('TXT_KEY_CITY_GABRIEL_ROOT_COUNCIL', 'Root Council'),
('TXT_KEY_CITY_GABRIEL_LANTERN_NEST', 'Lantern Nest'),
('TXT_KEY_SPY_GABRIEL_SCOUT_ONE', 'Myrmex'),
('TXT_KEY_SPY_GABRIEL_SCOUT_TWO', 'Tessera'),
('TXT_KEY_SPY_GABRIEL_SCOUT_THREE', 'Antenna'),
('TXT_KEY_SPY_GABRIEL_SCOUT_FOUR', 'Mandible'),

('TXT_KEY_LEADER_GABRIEL_FIRSTGREETING_1', 'We are many, though you see only one voice. I am Gabriel. If your purpose permits patience, our paths may strengthen one another.'),
('TXT_KEY_LEADER_GABRIEL_GREETING_FRIENDLY_1', 'Your signal is welcome. What shall our colonies prepare together?'),
('TXT_KEY_LEADER_GABRIEL_GREETING_NEUTRAL_1', 'You have my attention. State what you need, and what you are prepared to offer.'),
('TXT_KEY_LEADER_GABRIEL_GREETING_HOSTILE_1', 'Noise is not strength. Continue, if you wish us to measure yours.'),
('TXT_KEY_LEADER_GABRIEL_DECLAREWAR_1', 'Every trail has been marked, every chamber supplied. This outcome was prepared before you noticed it.'),
('TXT_KEY_LEADER_GABRIEL_ATTACKED_1', 'You gamble against ground you have not studied. The Colony does not.'),
('TXT_KEY_LEADER_GABRIEL_LOSEWAR_1', 'You have found the weak chamber. Enough loss; let us repair what remains.'),
('TXT_KEY_LEADER_GABRIEL_WINWAR_1', 'The field now says what I expected it to say. Accept peace, and we need not prove it again.'),
('TXT_KEY_LEADER_GABRIEL_DEFEATED_1', 'A colony may be scattered without being erased. Remember that when the quiet places begin to move.'),

('TXT_KEY_CIV5_GABRIEL_HEADING_1', 'The Colony'),
('TXT_KEY_CIV5_GABRIEL_TEXT_1', 'Many minds, one purpose.'),
('TXT_KEY_CIV5_GABRIEL_FACTOID_HEADING', 'Preparation'),
('TXT_KEY_CIV5_GABRIEL_FACTOID_TEXT', 'The Colony treats information as infrastructure. Its Nodes are observation posts, supply chambers, healing positions, and scientific relays at once.'),
('TXT_KEY_CIV5_GABRIEL_STRATEGY_HEADING', 'Colony Network'),
('TXT_KEY_CIV5_GABRIEL_STRATEGY_TEXT', 'Gabriel excels at Science and prepared defense. Rush him before Nodes mature, pillage established networks, attack from multiple directions, or force his army to fight far from home.'),
('TXT_KEY_CIV5_GABRIEL_VICTORY_HEADING', 'Victory Guidance'),
('TXT_KEY_CIV5_GABRIEL_VICTORY_TEXT', 'Science: Excellent. Diplomacy: Strong. Domination: Viable through counterattack. Culture: Viable but receives no direct specialization.');
